mapper.insert:

    SELECT #{occrClsfCd}
           || #{tskClsfCd}
           || LPAD(
                  (
                      COALESCE(
                          MAX(SUBSTR(MSG_ID, 6)::BIGINT) + 1,
                          1
                      )
                  )::TEXT,
                  5,
                  '0'
              ) AS MSG_ID
      FROM CLOVER_MSG_MNG
     WHERE OCCR_CLSF_CD = #{occrClsfCd}
       AND TSK_CLSF_CD = #{tskClsfCd}


INSERT INTO CLOVER_MSG_MNG (
      MSG_ID
    , MSG_CLSF
    , TSK_CLSF_CD
    , OCCR_CLSF_CD
    , MSG_PRNT_CD
    , MSG_CN
    , USE_YN
    , REG_DTTM
    , REGR_ID
    , CHGR_ID
) VALUES (
      #{msgId}
    , #{msgClsf}
    , #{tskClsfCd}
    , #{occrClsfCd}
    , #{msgPrntCd}
    , #{msgCn}
    , 'Y'
    , CURRENT_TIMESTAMP
    , #{regrId}
    , #{chgrId}
)

mapper.update:
UPDATE CLOVER_MSG_MNG
   SET MSG_CLSF     = #{msgClsf}
     , OCCR_CLSF_CD = #{occrClsfCd}
     , MSG_PRNT_CD  = #{msgPrntCd}
     , MSG_CN       = #{msgCn}
     , CHNG_DTTM    = CURRENT_TIMESTAMP
     , CHGR_ID      = #{chgrId}
 WHERE MSG_ID = #{msgId}

UPDATE CLOVER_MSG_MNG
   SET USE_YN = #{useYn}
 WHERE MSG_ID = #{msgId}
